// Layout e navegação reaproveitados do protótipo aprovado; dados injetados.
export function createPrototypeViews({state,DATA,rows,allScenario,metrics,offerView,detail,budgetCard,val,esc}){
function sectionTitle(title,sub='',action=''){return `<div class="sectionheader"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`}
function dashboard(){const base=allScenario(),filtered=rows();let focus=DATA.offers.find(o=>o.id===state.focus&&filtered.some(x=>x.id===o.id));if(!focus)focus=filtered.find(o=>val(o)!=null)||filtered[0];if(focus)state.focus=focus.id;const p=12,max=Math.max(1,Math.ceil(filtered.length/p));state.page=Math.max(1,Math.min(max,state.page));const subset=filtered.slice((state.page-1)*p,state.page*p);return `${metrics(filtered)}${sectionTitle('Resultados para o seu cenário', 'Opções reais da pesquisa, com simulação de gastos e situação das cotações.') }<div class="layout"><div class="card results"><div class="results-head"><div><h3>${filtered.length.toLocaleString('pt-BR')} combinações encontradas</h3><p>Ordenação não é recomendação: verifique a coluna de pendências.</p></div><div style="display:flex;gap:6px;align-items:center"><input aria-label="Buscar hospedagem" id="search" value="${esc(state.search)}" placeholder="Buscar hospedagem..." style="width:150px;height:44px;border:1px solid var(--border);border-radius:8px;padding:0 9px;font-size:14px"/><select id="sort" aria-label="Ordenação"><option value="ranking" ${state.sort==='ranking'?'selected':''}>Ranking por evidência</option><option value="price" ${state.sort==='price'?'selected':''}>Menor projeção</option><option value="priceHigh" ${state.sort==='priceHigh'?'selected':''}>Maior projeção</option><option value="missing" ${state.sort==='missing'?'selected':''}>Menos pendências</option><option value="hotel" ${state.sort==='hotel'?'selected':''}>Hospedagem mais barata</option></select></div></div>${subset.length?subset.map(offerView).join(''):`<div class="empty" style="margin:20px">Nenhuma combinação corresponde a estes filtros. Ajuste o teto ou o destino.</div>`}<div class="pagination"><span>Mostrando ${filtered.length?((state.page-1)*p+1):0}–${Math.min(state.page*p,filtered.length)} de ${filtered.length.toLocaleString('pt-BR')}</span><div class="pager"><button data-page="prev" ${state.page===1?'disabled':''}>Anterior</button><button data-page="next" ${state.page===max?'disabled':''}>Próxima</button></div></div></div><div class="rightcol">${detail(focus)}${budgetCard(base)}</div></div>`}
return {dashboard,sectionTitle};
}
